program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The frame around the repeating field has fixed colors.
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 3:
                out[r][c] = 1 if r < 2 else 4
            elif c < 3:
                out[r][c] = 1 if c < 2 else 4
    # Each interior row is a periodic color sequence. Ignore the small seed
    # motif at the upper-left (columns 3-5) when learning its period/phase.
    for r in range(3, h):
        known = [(c, grid[r][c]) for c in range(6, w) if grid[r][c] != 0]
        if not known:
            continue
        period = None
        mapping = None
        for p in range(2, 11):
            m = {}
            ok = True
            for c, v in known:
                k = c % p
                if k in m and m[k] != v:
                    ok = False
                    break
                m[k] = v
            if ok:
                period, mapping = p, m
                break
        if period is None:
            continue
        # Fill erased cells from the row's observed cycle. A residue missing
        # from the visible samples is learned by extending the cycle in either
        # direction from a known residue.
        for c in range(3, w):
            if out[r][c] != 0:
                continue
            k = c % period
            if k in mapping:
                out[r][c] = mapping[k]
            else:
                nearest = min(mapping, key=lambda q: min((q-k)%period, (k-q)%period))
                # infer the color order by following the known sequence where possible
                # (a missing residue is rare for these large grids); leave unchanged otherwise.
                out[r][c] = mapping[nearest]
    return out
'''
